Analisando o problema, uma string $S_k$ é substring da concatenação $S_a S_b$ (com $a, b < k$) se, e somente se, existir uma divisão de $S_k$ em duas partes: um prefixo de tamanho $p$ e um sufixo de tamanho $|S_k| - p$ (para algum $0 \le p \le |S_k|$), tais que:
1. O prefixo de $S_k$ de tamanho $p$ seja um sufixo de alguma string $S_a$ anterior ($a < k$);
2. O sufixo de $S_k$ de tamanho $|S_k| - p$ seja um prefixo de alguma string $S_b$ anterior ($b < k$).

Como $a$ e $b$ podem ser escolhidos de forma independente dentre os índices menores que $k$ (e para $k \ge 2$ sempre existem strings anteriores para satisfazer a parte vazia quando $p = 0$ ou $p = |S_k|$), basta manter o conjunto de todos os sufixos e o conjunto de todos os prefixos das strings anteriores. 

Como as strings têm comprimento pequeno ($\le 10$), podemos usar uma árvore Trie para armazenar prefixos e outra para sufixos, permitindo verificações e inserções em tempo $O(|S_k|)$, tornando a solução extremamente eficiente.

Abaixo está a solução completa em Java:

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isEnd = false;
    }

    static class Trie {
        TrieNode root = new TrieNode();

        void insert(String s, boolean reverse) {
            TrieNode curr = root;
            int n = s.length();
            for (int i = 0; i < n; i++) {
                int idx = reverse ? (s.charAt(n - 1 - i) - 'a') : (s.charAt(i) - 'a');
                if (curr.children[idx] == null) {
                    curr.children[idx] = new TrieNode();
                }
                curr = curr.children[idx];
                curr.isEnd = true; // Todo prefixo inserido é válido
            }
        }

        boolean contains(String s, int start, int end, boolean reverse) {
            if (start == end) return true; // String vazia é sempre válida para k >= 2
            TrieNode curr = root;
            if (!reverse) {
                for (int i = start; i < end; i++) {
                    int idx = s.charAt(i) - 'a';
                    if (curr.children[idx] == null) return false;
                    curr = curr.children[idx];
                }
            } else {
                for (int i = end - 1; i >= start; i--) {
                    int idx = s.charAt(i) - 'a';
                    if (curr.children[idx] == null) return false;
                    curr = curr.children[idx];
                }
            }
            return curr.isEnd;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        String[] s = new String[n];
        for (int i = 0; i < n; i++) {
            s[i] = scanner.next();
        }

        Trie prefixTrie = new Trie();
        Trie suffixTrie = new Trie();

        for (int k = 0; k < n; k++) {
            String curr = s[k];
            int len = curr.length();

            if (k > 0) {
                boolean invalid = false;
                for (int p = 0; p <= len; p++) {
                    // Prefixo curr[0...p-1] precisa ser sufixo de alguma string anterior
                    boolean prefixValid = (p == 0) || suffixTrie.contains(curr, 0, p, true);
                    if (prefixValid) {
                        // Sufixo curr[p...len-1] precisa ser prefixo de alguma string anterior
                        boolean suffixValid = (p == len) || prefixTrie.contains(curr, p, len, false);
                        if (suffixValid) {
                            invalid = true;
                            break;
                        }
                    }
                }

                if (invalid) {
                    System.out.println(curr);
                    return;
                }
            }

            // Insere todos os prefixos de curr
            prefixTrie.insert(curr, false);
            // Insere todos os sufixos de curr invertidos na suffixTrie
            suffixTrie.insert(curr, true);
        }

        System.out.println("ok");
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}
